function cdqPdfDriveUrlV2267(id){
  return 'https://drive.google.com/file/d/'+encodeURIComponent(String(id||''))+'/view';
}

function cdqPdfIntentV2267(id,packageName){
  const fileId=encodeURIComponent(String(id||''));
  const driveUrl=cdqPdfDriveUrlV2267(id);
  let intent='intent://drive.google.com/file/d/'+fileId+'/view#Intent;scheme=https;action=android.intent.action.VIEW;type=application/pdf;';
  if(packageName)intent+='package='+packageName+';';
  intent+='S.browser_fallback_url='+encodeURIComponent(driveUrl)+';end';
  return intent;
}

function cdqMarquerPdfOuvertV2267(id){
  if(String(utilisateurCourantRole||'')==='lecture')return;
  try{
    fichierOuvertPourModification=id;
    let ancienneDate='';
    const checkbox=document.querySelector('.file-checkbox[data-file-id="'+String(id).replace(/[^\w-]/g,'')+'"]');
    const ligne=checkbox&&checkbox.closest('.file-row');
    if(ligne)ancienneDate=ligne.dataset.modification||'';
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',ancienneDate);
    sessionStorage.setItem('momentModification',String(Date.now()));
  }catch(_){}
}

function cdqOuvrirPdfAndroidV2267(id){
  const pref=cdqPdfReaderPreference();
  cdqMarquerPdfOuvertV2267(id);
  afficherMessage('Préparation du PDF…',true);

  // Le lecteur CDQ reste le seul choix qui charge volontairement le PDF dans l'application.
  if(pref==='cdq'){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  let target;
  if(pref==='ilovepdf'){
    target=cdqPdfIntentV2267(id,'com.ilovepdf.www');
  }else if(pref==='acrobat'){
    target=cdqPdfIntentV2267(id,'com.adobe.reader');
  }else{
    // "Demander" : intent PDF sans package pour laisser Android proposer les apps compatibles.
    target=cdqPdfIntentV2267(id,'');
  }

  // Ouverture DIRECTE pendant le toucher : pas de fenêtre about:blank intermédiaire.
  const opened=window.open(target,'_blank','noopener');
  if(!opened){
    try{window.location.href=target;}catch(_){
      window.open(cdqPdfDriveUrlV2267(id),'_blank','noopener');
    }
  }
  return true;
}

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    if(navigator.onLine!==false){
      if(/Android/i.test(navigator.userAgent||'')){
        return cdqOuvrirPdfAndroidV2267(id);
      }
      return cdqV19OldModify(id);
    }
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(!navigator.onLine){
    afficherMessage('Ouvrez ce fichier dans son application après l’avoir enregistré sur le téléphone.',false);
    return;
  }
  return cdqV19OldModify(id);
};

